"use client";

import React, { useEffect } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { UnicornScene } from "unicornstudio-react";
import { Activity, BrainCircuit, Wrench, Shield } from "lucide-react";

export function LandingView({ onEnterAegis }: { onEnterAegis: () => void }) {
    const { scrollY } = useScroll();
    const yText = useTransform(scrollY, [0, 1000], [0, -400]);

    // Remove Unicorn Studio watermark from DOM
    useEffect(() => {
        const removeWatermark = () => {
            document.querySelectorAll('a[href*="unicorn.studio"]').forEach(node => node.remove());
        };
        // It might be injected asynchronously, so we observe or poll briefly
        const interval = setInterval(removeWatermark, 500);
        setTimeout(() => clearInterval(interval), 5000); // stop polling after 5s

        return () => clearInterval(interval);
    }, []);

    return (
        <div className="relative w-full text-white min-h-screen">
            {/* Sticky Navigation */}
            <nav className="fixed top-0 left-0 right-0 z-50 h-20 flex items-center justify-between px-8 bg-[#0F1117]/60 backdrop-blur-[16px] border-b border-white/5">
                <div className="flex items-center gap-3">
                    <Shield className="w-6 h-6 text-[#E0B0FF]" />
                    <span className="font-bold tracking-widest text-lg">AEGIS SRE</span>
                </div>
                <div className="flex gap-8 text-sm font-medium text-gray-400">
                    <div className="relative text-white cursor-pointer transition-colors hover:text-white">
                        Overview
                        <div className="absolute -bottom-7 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-[#E0B0FF] to-transparent" />
                    </div>
                    <div className="cursor-pointer transition-colors hover:text-white">Capabilities</div>
                    <div className="cursor-pointer transition-colors hover:text-white">Architecture</div>
                </div>
                <button
                    onClick={onEnterAegis}
                    className="px-6 py-2 rounded-full glass-panel text-sm font-semibold tracking-wide hover:shadow-[0_0_15px_rgba(224,176,255,0.3)] transition-all"
                >
                    Launch Console
                </button>
            </nav>

            {/* Background - Unicorn Studio (Only in Hero) */}
            <div
                className="fixed top-0 left-0 w-full h-[100vh] pointer-events-none"
                style={{
                    zIndex: -1,
                    maskImage: "linear-gradient(to bottom, black 70%, transparent 100%)",
                    WebkitMaskImage: "linear-gradient(to bottom, black 70%, transparent 100%)"
                }}
            >
                <UnicornScene
                    projectId="ye7FVUbWpTAYh806M04d"
                    // @ts-ignore
                    width="100%"
                    height="100%"
                />
            </div>

            {/* Hero Section */}
            <section className="h-screen flex flex-col items-center justify-center w-full relative z-10 pt-20">
                <motion.div
                    style={{ y: yText }}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ duration: 0.8, ease: "easeOut" }}
                    className="flex flex-col items-center"
                >
                    <h1 className="text-7xl md:text-9xl font-extrabold tracking-tighter text-gradient mb-8 drop-shadow-2xl relative">
                        {/* Subtle top glow line */}
                        <div className="absolute -top-4 left-1/4 right-1/4 h-[1px] bg-gradient-to-r from-transparent via-[#E0B0FF]/50 to-transparent blur-[2px]"></div>
                        AEGIS SRE
                    </h1>
                    <p className="text-xl md:text-2xl text-gray-300 max-w-2xl text-center mb-12 font-medium tracking-wide">
                        Enterprise Reliability Command System
                    </p>

                    <motion.button
                        onClick={onEnterAegis}
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        className="px-10 py-4 rounded-full glass-panel border border-[#E0B0FF]/20 text-lg font-semibold tracking-wider transition-all hover:bg-white/10 hover:shadow-[0_0_20px_rgba(224,176,255,0.2)]"
                    >
                        Initialize Agent
                    </motion.button>
                </motion.div>
            </section>

            {/* Hero -> Content Transition Bar */}
            <div
                className="w-full h-[120px] relative z-10"
                style={{
                    background: "linear-gradient(to bottom, rgba(15,17,23,0) 0%, rgba(15,17,23,0.6) 40%, #0F1117 100%)",
                    borderTop: "1px solid rgba(255,255,255,0.06)"
                }}
            />

            {/* Content Sections */}
            <div className="relative z-10 bg-[#0F1117] w-full min-h-screen">
                <div className="max-w-6xl mx-auto px-6 py-24">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {[
                            {
                                icon: <Activity className="w-6 h-6 text-[#E0B0FF]" />,
                                title: "Observe",
                                desc: "Monitor telemetry, traces, and critical metrics across the entire architectural stack with sub-second precision.",
                                metric: "99.999% SLA Uptime"
                            },
                            {
                                icon: <BrainCircuit className="w-6 h-6 text-[#E0B0FF]" />,
                                title: "Reason",
                                desc: "Automate root cause analysis with LLM-powered insights, correlating spikes and anomalies instantaneously.",
                                metric: "< 200ms Inference"
                            },
                            {
                                icon: <Wrench className="w-6 h-6 text-[#E0B0FF]" />,
                                title: "Act",
                                desc: "Execute remediation workflows, scale infrastructure, or rollback deployments seamlessly from the command center.",
                                metric: "0 Human Interventions"
                            },
                        ].map((item, idx) => (
                            <motion.div
                                key={idx}
                                initial={{ opacity: 0, y: 20 }}
                                whileInView={{ opacity: 1, y: 0 }}
                                viewport={{ once: true, margin: "-50px" }}
                                transition={{ duration: 0.5, delay: idx * 0.1 }}
                                className="glass-panel p-8 rounded-2xl w-full flex flex-col h-full border border-white/5 transition-all hover:-translate-y-1 hover:border-[#E0B0FF]/30 hover:shadow-[0_8px_30px_rgba(224,176,255,0.05)] group relative overflow-hidden"
                            >
                                {/* Inner highlight */}
                                <div className="absolute inset-x-0 -top-px h-px bg-gradient-to-r from-transparent via-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                                <div className="mb-6 p-3 rounded-xl bg-white/5 inline-flex self-start border border-white/10 group-hover:bg-[#E0B0FF]/10 transition-colors">
                                    {item.icon}
                                </div>
                                <h2 className="text-2xl font-bold mb-3 text-white">{item.title}</h2>
                                <p className="text-gray-400 mb-8 flex-1 leading-relaxed">{item.desc}</p>

                                <div className="pt-4 border-t border-white/10">
                                    <span className="text-xs font-mono uppercase tracking-wider text-[#E0B0FF]/80">{item.metric}</span>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}
